221	/// CR 119.1: Apply a post-replacement `ProposedEvent::LifeGain` to the game state.
222	///
223	/// Extracted from `apply_life_gain`'s Execute arm so the same mutation can be
224	/// invoked by `handle_replacement_choice` when a player accepts a life-gain
225	/// replacement choice. Caller is responsible for emitting `EffectResolved`.
226	pub fn apply_life_gain_after_replacement(
227	    state: &mut GameState,
228	    event: ProposedEvent,
229	    events: &mut Vec<GameEvent>,
230	) -> u32 {
231	    let ProposedEvent::LifeGain {
232	        player_id: pid,
233	        amount: gain_amount,
234	        ..
235	    } = event
236	    else {
237	        debug_assert!(
238	            false,
239	            "apply_life_gain_after_replacement called with non-LifeGain ProposedEvent"
240	        );
241	        return 0;
242	    };
243	    // CR 119.8: gaining 0 life doesn't count as gaining life — no state
244	    // mutation and no journal command; the event below still fires as before.
245	    if gain_amount != 0 {
246	        state
247	            .resolve_and_apply_player_edit(
248	                pid,
249	                ResolvedPlayerEdit::Life {
250	                    delta: gain_amount as i32,
251	                },
252	            )
253	            .expect("post-replacement life gain must target a live player");
254	    }
255	    // CR 611.3a + CR 119: gate escalation on a live life-reading static.
256	    crate::game::layers::mark_layers_full_if_life_reading_static_live(state);
257	    events.push(GameEvent::LifeChanged {
258	        player_id: pid,
259	        amount: gain_amount as i32,
260	    });
261	    gain_amount
262	}
