264	/// CR 119.3: An effect that causes a player to lose life subtracts that much
265	/// from the player's life total.
266	/// Returns the actual amount of life lost (may differ due to replacements like doubling).
267	/// Returns `Err(ReplacementDeferred)` whenever the replacement/substitution
268	/// pipeline pauses for player input.
269	pub fn apply_life_loss(
270	    state: &mut GameState,
271	    player_id: PlayerId,
272	    amount: u32,
273	    events: &mut Vec<GameEvent>,
274	) -> Result<u32, ReplacementDeferred> {
275	    if amount == 0 {
276	        return Ok(0);
277	    }
278	    // CR 119.8: A player who can't lose life is unaffected. Short-circuit
279	    // before the replacement pipeline.
280	    if crate::game::static_abilities::player_has_cant_lose_life(state, player_id) {
281	        return Ok(0);
282	    }
283	    let proposed = ProposedEvent::LifeLoss {
284	        player_id,
285	        amount,
286	        applied: HashSet::new(),
287	    };
288	    match replacement::replace_event(state, proposed, events) {
289	        ReplacementResult::Execute(event) => {
290	            let lost = apply_life_loss_after_replacement(state, event, events);
291	            // CR 614.6: A replacement that substitutes another effect must
292	            // finish that effect before the original resolution may continue.
293	            match drain_substitution_continuation(state, events) {
294	                SubstitutionDrainOutcome::Completed => Ok(lost),
295	                SubstitutionDrainOutcome::Deferred => {
296	                    Err(ReplacementDeferred::SubstitutionContinuation)
297	                }
298	            }
299	        }
300	        ReplacementResult::Prevented => {
301	            // CR 614.1a + CR 614.6 — Issue #317: Drain substitute effect
302	            // stashed by cross-event-type replacement.
303	            match drain_substitution_continuation(state, events) {
304	                SubstitutionDrainOutcome::Completed => Ok(0),
305	                SubstitutionDrainOutcome::Deferred => {
306	                    Err(ReplacementDeferred::SubstitutionContinuation)
307	                }
308	            }
309	        }
310	        ReplacementResult::NeedsChoice(player) => {
311	            // CR 616.1: Multiple competing replacements — player must choose.
312	            state.waiting_for =
313	                crate::game::replacement::replacement_choice_waiting_for(player, state);
314	            Err(ReplacementDeferred::ReplacementChoice)
315	        }
316	    }
317	}
