331	/// CR 119.3: Apply a post-replacement `ProposedEvent::LifeLoss` to the game state.
332	///
333	/// Extracted from `apply_life_loss`'s Execute arm so the same mutation can
334	/// be invoked by `handle_replacement_choice` when a player accepts a life-loss
335	/// replacement choice. Caller is responsible for emitting `EffectResolved`.
336	pub fn apply_life_loss_after_replacement(
337	    state: &mut GameState,
338	    event: ProposedEvent,
339	    events: &mut Vec<GameEvent>,
340	) -> u32 {
341	    let ProposedEvent::LifeLoss {
342	        player_id: pid,
343	        amount: loss_amount,
344	        ..
345	    } = event
346	    else {
347	        debug_assert!(
348	            false,
349	            "apply_life_loss_after_replacement called with non-LifeLoss ProposedEvent"
350	        );
351	        return 0;
352	    };
353	    // CR 119.8: losing 0 life doesn't count as losing life — no state
354	    // mutation and no journal command; the event below still fires as before.
355	    if loss_amount != 0 {
356	        let before = crate::game::players::team_life_total(state, pid);
357	        state
358	            .resolve_and_apply_player_edit(
359	                pid,
360	                ResolvedPlayerEdit::Life {
361	                    delta: -(loss_amount as i32),
362	                },
363	            )
364	            .expect("post-replacement life loss must target a live player");
365	        let after = crate::game::players::team_life_total(state, pid);
366	        // The clone-local preview observes the real edit before events or a
367	        // substitution continuation can introduce later, unrelated work.
368	        crate::game::life_safety::record_life_mutation_receipt(
369	            state,
370	            pid,
371	            before,
372	            after,
373	            loss_amount,
374	        );
375	    }
376	    // CR 611.3a + CR 119 + CR 120.3a: gate escalation on a live life-reading
377	    // static. Also the sink for non-infect player damage (deal_damage.rs).
378	    crate::game::layers::mark_layers_full_if_life_reading_static_live(state);
379	    events.push(GameEvent::LifeChanged {
380	        player_id: pid,
381	        amount: -(loss_amount as i32),
382	    });
383	    loss_amount
384	}
