386	/// Outcome of applying a life-total permutation via `apply_life_totals_assignment`.
387	///
388	/// Typed (not a bare bool) so the control-flow signal is self-documenting at
389	/// call sites: `Applied` means the caller should emit its `EffectResolved`;
390	/// `Deferred` means a competing replacement (CR 616.1) installed a choice
391	/// `WaitingFor` and the caller must return without emitting — the resume path
392	/// completes resolution.
393	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
394	pub enum LifeAssignmentOutcome {
395	    Applied,
430	                .map(|p| p.life)
431	                .ok_or(EffectError::PlayerNotFound)?;
432	            Ok((pid, new_life - old))
433	        })
434	        .collect::<Result<Vec<_>, EffectError>>()?;
435	
436	    for (index, (pid, diff)) in deltas.iter().copied().enumerate() {
437	        let deferred = match diff.signum() {
438	            1 => apply_life_gain(state, pid, diff as u32, events).err(),
439	            -1 => apply_life_loss(state, pid, (-diff) as u32, events).err(),
440	            _ => None,
441	        };
442	        if deferred.is_some() {
443	            // CR 616.1: a competing replacement required a player choice; the
444	            // helper installed the WaitingFor and the resume path completes the
445	            // remaining assignments.
446	            state.push_life_total_assignment(PendingLifeTotalAssignment {
447	                completion_player,
448	                remaining: deltas[index + 1..].to_vec(),
449	                completion: completion.clone(),
450	            });
451	            return Ok(LifeAssignmentOutcome::Deferred);
452	        }
453	    }
454	    Ok(LifeAssignmentOutcome::Applied)
455	}
