457	pub(crate) fn drain_pending_life_total_assignment(
458	    state: &mut GameState,
459	    events: &mut Vec<GameEvent>,
460	) {
461	    while let Some(mut pending) = state.take_active_life_total_assignment() {
462	        state.waiting_for = WaitingFor::Priority {
463	            player: pending.completion_player,
464	        };
465	
466	        let Some((pid, diff)) = pending.remaining.first().copied() else {
467	            complete_pending_life_total_assignment(state, pending, events);
468	            if !matches!(state.waiting_for, WaitingFor::Priority { .. }) {
469	                return;
470	            }
471	            continue;
472	        };
473	
474	        pending.remaining.remove(0);
475	        state.push_life_total_assignment(pending);
476	
477	        let deferred = match diff.signum() {
478	            1 => apply_life_gain(state, pid, diff as u32, events).err(),
479	            -1 => apply_life_loss(state, pid, (-diff) as u32, events).err(),
480	            _ => None,
481	        };
482	        if deferred.is_some() || !matches!(state.waiting_for, WaitingFor::Priority { .. }) {
483	            return;
484	        }
485	    }
486	}
