488	fn complete_pending_life_total_assignment(
489	    state: &mut GameState,
490	    pending: PendingLifeTotalAssignment,
491	    events: &mut Vec<GameEvent>,
492	) {
493	    state.waiting_for = WaitingFor::Priority {
494	        player: pending.completion_player,
495	    };
496	
497	    if let Some(PendingEffectResolved {
498	        kind,
499	        source_id,
500	        resolution_event,
501	        post_actions,
502	        player_action,
503	    }) = pending.completion
504	    {
505	        debug_assert!(
506	            post_actions.is_empty(),
507	            "life-total assignment completion does not support counter post-actions"
508	        );
509	        match resolution_event {
510	            PendingEffectResolutionEvent::Emit => {
640	        // stay fixed to the caster. Single-player and caster-scoped forms
641	        // ("becomes 10", "your life total", Repay in Kind's cross-player
642	        // extremum) are unaffected — they carry no `ScopedPlayer` ref to vary.
643	        let mut scoped_ability = ability.clone();
644	        scoped_ability.set_scoped_player_recursive(target_player_id);
645	        let amount = crate::game::quantity::resolve_quantity_with_targets(
646	            state,
647	            amount_expr,
648	            &scoped_ability,
649	        );
650	
651	        // CR 810.9a: "If a cost or effect needs to know the value of an
652	        // individual player's life total, that cost or effect uses the
653	        // team's life total instead" — degenerates to `Player::life` outside
654	        // team-based formats. CR 810.9c: the diff is still applied to only
655	        // `target_player_id`'s own life, so the team total moves by exactly
656	        // the gained/lost amount.
657	        if !state.players.iter().any(|p| p.id == target_player_id) {
658	            return Err(EffectError::PlayerNotFound);
659	        }
660	        let current_life = crate::game::players::team_life_total(state, target_player_id);
661	        let diff = amount - current_life;
662	
663	        let deferred = match diff.signum() {
664	            1 => apply_life_gain(state, target_player_id, diff as u32, events).err(),
665	            -1 => apply_life_loss(state, target_player_id, (-diff) as u32, events).err(),
666	            _ => None,
667	        };
