 30	/// Outcome of attempting to pay life as a cost.
 31	///
 32	/// CR 119.4b: Paying 0 life always succeeds — even under a prohibition — and
 33	/// is represented by `Paid { amount: 0 }`.
 34	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
 35	pub enum PayLifeCostResult {
 36	    /// The full amount was deducted (or amount was 0, always payable per CR 119.4b).
 37	    Paid { amount: u32 },
 38	    /// CR 118.11 + CR 614.6: The cost is paid even though a replacement
 39	    /// modified its life-loss action, and that replacement's substitute has
 40	    /// paused for player input. `state.waiting_for` owns the continuation.
 41	    PaidWithDeferredSubstitution { amount: u32 },
 42	    /// CR 118.3b + CR 119.4 + CR 616.1: The life-payment event is awaiting
 43	    /// replacement ordering before it can be applied. No payment failure has
 44	    /// occurred; the caller must park its typed outer action until the chosen
 45	    /// replacement finishes.
 46	    DeferredReplacementChoice {
 47	        amount: u32,
 48	        choice_player: PlayerId,
 49	    },
 50	    /// CR 118.3: Player's life total is below `amount` — cost can't be paid.
 51	    InsufficientLife,
 52	    /// CR 119.8 / CR 118.3: A static prohibition makes the cost unpayable.
 53	    Prohibited,
 54	}
 55	
 56	impl PayLifeCostResult {
 57	    /// Returns `true` if the cost was successfully paid (including the zero-life case).
 58	    pub fn is_paid(self) -> bool {
 59	        matches!(
 60	            self,
 61	            PayLifeCostResult::Paid { .. } | PayLifeCostResult::PaidWithDeferredSubstitution { .. }
 62	        )
 63	    }
 64	
 65	    /// Returns `true` if the cost was NOT paid (insufficient life or prohibited).
 66	    pub fn is_unpayable(self) -> bool {
 67	        matches!(
 68	            self,
 69	            PayLifeCostResult::InsufficientLife | PayLifeCostResult::Prohibited
 70	        )
 71	    }
 72	}
