 74	/// CR 107.4f + CR 118.3 + CR 119.8: How many Phyrexian 2-life payments can this
 75	/// player afford, given their current life total and pay-life prohibition status?
 76	///
 77	/// Threaded into [`crate::game::mana_payment::can_pay_for_spell`] so Phyrexian
 78	/// shards without an available mana option are only treated as payable when the
 79	/// player has the life budget to cover them.
 80	///
 81	/// Returns 0 under CantLoseLife (CR 119.8), direct can't-pay-life statics, or
 82	/// when the player isn't found.
 83	/// Otherwise floor-divides current life by 2 (CR 118.3: must have the resource
 84	/// to pay fully).
 85	pub fn max_phyrexian_life_payments(state: &GameState, player: PlayerId) -> u32 {
 86	    // CR 119.8 / CR 118.3: A cost that involves paying life can't be paid while prohibited.
 87	    if player_has_cant_lose_life(state, player) || player_cant_pay_life_as_cost(state, player) {
 88	        return 0;
 89	    }
 90	    // CR 119.4a: in a team format the payable budget is bounded by the team total.
 91	    u32::try_from((crate::game::players::team_life_total(state, player) / 2).max(0)).unwrap_or(0)
 92	}
