 94	/// CR 118.3 + CR 119.4b + CR 119.8: Pure predicate — can this player pay `amount` life?
 95	///
 96	/// General cost-resource predicate. Cast/activation validation that must also
 97	/// honor direct "can't pay life" statics uses
 98	/// [`can_pay_life_cast_or_activation_cost`].
 99	pub fn can_pay_life_cost(state: &GameState, player: PlayerId, amount: u32) -> bool {
100	    // CR 119.4b: 0 life is always payable, even under pay-life prohibitions.
101	    if amount == 0 {
102	        return true;
103	    }
104	    // CR 119.8: "a cost that involves having that player pay life can't be paid."
105	    if player_has_cant_lose_life(state, player) {
106	        return false;
107	    }
108	    // CR 119.4a: in a team format affordability is bounded by the team's
109	    // shared life total (off-team this is the player's own life).
110	    crate::game::players::team_life_total(state, player) >= amount as i32
111	}
