113	/// CR 118.3b + CR 119.4 + CR 119.8: Pay `amount` life from `player` as a cost.
114	///
115	/// Routes the life deduction through [`apply_life_loss`] per CR 119.4
116	/// ("paying life IS losing life"), so the replacement pipeline and the
117	/// `CantLoseLife` short-circuit run consistently with every other life-loss event.
118	///
119	/// Returns a [`PayLifeCostResult`] describing the outcome. The caller is
120	/// responsible for translating an unpayable result into the appropriate
121	/// failure signal for their context (cost-payment flag, `EngineError`, etc.).
122	///
123	/// Defense in depth: the prohibition check happens here AND inside
124	/// `apply_life_loss`. This module is also called from pre-validation
125	/// paths which may not have reached the executor yet, so checking at the cost
126	/// boundary keeps the result enum accurate.
127	pub fn pay_life_as_cost(
128	    state: &mut GameState,
129	    player: PlayerId,
130	    amount: u32,
131	    events: &mut Vec<GameEvent>,
132	) -> PayLifeCostResult {
133	    // CR 119.4b: Paying 0 life always succeeds, no event emitted.
134	    if amount == 0 {
135	        return PayLifeCostResult::Paid { amount: 0 };
136	    }
137	
138	    // CR 119.8: Lock → cost can't be paid.
139	    if player_has_cant_lose_life(state, player) {
140	        return PayLifeCostResult::Prohibited;
141	    }
142	
143	    // CR 119.4a: Resource check — affordability is bounded by the team's
144	    // shared total. The DEDUCTION below lands on the individual `Player::life`
145	    // (CR 810.9: life loss happens to each player individually) and may go
146	    // negative — only the affordability gate reads the team total.
147	    let has_life = crate::game::players::team_life_total(state, player) >= amount as i32;
148	    if !has_life {
149	        return PayLifeCostResult::InsufficientLife;
150	    }
151	
152	    // CR 119.4: Pay life is life loss — route through the damage/life-loss helper
153	    // so the replacement pipeline fires. CR 118.11: a replacement may modify
154	    // the action performed while paying, but the cost is still paid. Preserve
155	    // the typed paused-substitute outcome so callers cannot confuse a paid
156	    // cost whose replacement is still resolving with insufficient life.
157	    match apply_life_loss(state, player, amount, events) {
158	        Ok(_) => PayLifeCostResult::Paid { amount },
159	        Err(ReplacementDeferred::ReplacementChoice) => {
160	            let WaitingFor::ReplacementChoice {
161	                player: choice_player,
162	                ..
163	            } = &state.waiting_for
164	            else {
165	                unreachable!("replacement deferral must expose its ordering player")
166	            };
167	            PayLifeCostResult::DeferredReplacementChoice {
168	                amount,
169	                choice_player: *choice_player,
170	            }
171	        }
172	        Err(ReplacementDeferred::SubstitutionContinuation) => {
173	            PayLifeCostResult::PaidWithDeferredSubstitution { amount }
174	        }
175	    }
176	}
